import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_attention_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <mma.h>

using namespace cute;

__device__ __forceinline__ float h2f(__half h) { return __half2float(h); }
__device__ __forceinline__ __half f2h(float f) { return __float2half(f); }
__device__ __forceinline__ void my_cp_async_cg_16(void* smem_ptr, const void* gmem_ptr) {
    unsigned int smem_addr = static_cast<unsigned int>(__cvta_generic_to_shared(smem_ptr));
    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" :: "r"(smem_addr), "l"(gmem_ptr));
}
__device__ __forceinline__ void my_cp_async_commit() {
    asm volatile("cp.async.commit_group;\n");
}
template<int N>
__device__ __forceinline__ void my_cp_async_wait() {
    asm volatile("cp.async.wait_group %0;\n" :: "n"(N));
}

// Compile-time tile sizes.
constexpr int BLOCK_M = 32;   // rows of Q processed per CTA
constexpr int BLOCK_D = 32;   // chunk of head-dim processed at a time
constexpr int THREADS = 256;  // threads per block
constexpr int MAX_ACC = 64;   // upper bound of (BLOCK_M*N)/THREADS per thread

__global__ void attention_kernel(
    const __half* __restrict__ Q,
    const __half* __restrict__ K,
    const __half* __restrict__ V,
    __half* __restrict__ O,
    int B, int H, int N, int D,
    float scale)
{
    int b = blockIdx.z;
    int h = blockIdx.y;
    int m_tile = blockIdx.x;
    int m_base = m_tile * BLOCK_M;

    int64_t bh_stride = (int64_t)N * D;
    int64_t bh_idx = (int64_t)b * H + h;

    const __half* Qptr = Q + bh_idx * bh_stride;
    const __half* Kptr = K + bh_idx * bh_stride;
    const __half* Vptr = V + bh_idx * bh_stride;
    __half* Optr = O + bh_idx * bh_stride;

    auto mQ = make_tensor(make_gmem_ptr(Qptr), make_shape(N, D), make_stride(D, Int<1>{}));
    auto mK = make_tensor(make_gmem_ptr(Kptr), make_shape(N, D), make_stride(D, Int<1>{}));
    auto mV = make_tensor(make_gmem_ptr(Vptr), make_shape(N, D), make_stride(D, Int<1>{}));
    auto mO = make_tensor(make_gmem_ptr(Optr), make_shape(N, D), make_stride(D, Int<1>{}));

    extern __shared__ unsigned char smem_raw[];
    __half* Qs_buf0  = reinterpret_cast<__half*>(smem_raw);
    __half* Qs_buf1  = Qs_buf0 + BLOCK_M * BLOCK_D;
    __half* KVs_buf0 = Qs_buf1 + BLOCK_M * BLOCK_D;
    __half* KVs_buf1 = KVs_buf0 + (size_t)N * BLOCK_D;
    float*  S_ptr    = reinterpret_cast<float*>(KVs_buf1 + (size_t)N * BLOCK_D);
    auto sS  = make_tensor(make_smem_ptr(S_ptr),   make_shape(Int<BLOCK_M>{}, N), make_stride(N, Int<1>{}));
    __half* Qbuf[2] = { Qs_buf0, Qs_buf1 };
    __half* Kbuf[2] = { KVs_buf0, KVs_buf1 };
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    int warp_id = tid / 32;
    int lane = tid % 32;
    int nwarps = nthreads / 32;
    int num_dchunks = D / BLOCK_D;
    int qelems8 = (BLOCK_M * BLOCK_D) / 8;
    int kelems8 = (N * BLOCK_D) / 8;
    auto load_qk_chunk = [&](int c, int buf) {
        int d0 = c * BLOCK_D;
        for (int idx = tid; idx < qelems8; idx += nthreads) {
            int m = idx / (BLOCK_D / 8);
            int d8 = idx % (BLOCK_D / 8);
            int gidx = (m_base + m) * D + d0 + d8 * 8;
            my_cp_async_cg_16(&Qbuf[buf][m * BLOCK_D + d8 * 8], &Qptr[gidx]);
        }
        for (int idx = tid; idx < kelems8; idx += nthreads) {
            int n = idx / (BLOCK_D / 8);
            int d8 = idx % (BLOCK_D / 8);
            int gidx = n * D + d0 + d8 * 8;
            my_cp_async_cg_16(&Kbuf[buf][n * BLOCK_D + d8 * 8], &Kptr[gidx]);
        }
        my_cp_async_commit();
    };
    // ---- Pass 1: S = Q @ K^T using Tensor Core WMMA (accumulated over head-dim chunks, double-buffered) ----
    constexpr int WMMA_M = 16, WMMA_N = 16, WMMA_K = 16;
    constexpr int MAX_TILES_PER_WARP = 8;
    const int num_m_tiles = BLOCK_M / WMMA_M;
    const int num_n_tiles = N / WMMA_N;
    const int num_wk_per_chunk = BLOCK_D / WMMA_K;
    const int total_tiles = num_m_tiles * num_n_tiles;
    const int tiles_per_warp = (total_tiles + nwarps - 1) / nwarps;
    nvcuda::wmma::fragment<nvcuda::wmma::accumulator, WMMA_M, WMMA_N, WMMA_K, float> acc_frag[MAX_TILES_PER_WARP];
    #pragma unroll
    for (int t = 0; t < MAX_TILES_PER_WARP; ++t) {
        nvcuda::wmma::fill_fragment(acc_frag[t], 0.0f);
    }
    int cur = 0;
    load_qk_chunk(0, cur);
    my_cp_async_wait<0>();
    __syncthreads();
    for (int c = 0; c < num_dchunks; ++c) {
        int nxt = 1 - cur;
        if (c + 1 < num_dchunks) {
            load_qk_chunk(c + 1, nxt);
        }
        __half* Qs_ptr = Qbuf[cur];
        __half* KVs_ptr = Kbuf[cur];
        for (int t = 0; t < tiles_per_warp; ++t) {
            int tile_idx = warp_id + t * nwarps;
            if (tile_idx >= total_tiles) continue;
            int mt = tile_idx / num_n_tiles;
            int nt = tile_idx % num_n_tiles;
            #pragma unroll
            for (int wk = 0; wk < num_wk_per_chunk; ++wk) {
                nvcuda::wmma::fragment<nvcuda::wmma::matrix_a, WMMA_M, WMMA_N, WMMA_K, __half, nvcuda::wmma::row_major> a_frag;
                nvcuda::wmma::fragment<nvcuda::wmma::matrix_b, WMMA_M, WMMA_N, WMMA_K, __half, nvcuda::wmma::col_major> b_frag;
                nvcuda::wmma::load_matrix_sync(a_frag, Qs_ptr + mt * WMMA_M * BLOCK_D + wk * WMMA_K, BLOCK_D);
                nvcuda::wmma::load_matrix_sync(b_frag, KVs_ptr + nt * WMMA_N * BLOCK_D + wk * WMMA_K, BLOCK_D);
                nvcuda::wmma::mma_sync(acc_frag[t], a_frag, b_frag, acc_frag[t]);
            }
        }
        if (c + 1 < num_dchunks) {
            my_cp_async_wait<0>();
        }
        __syncthreads();
        cur = nxt;
    }
    for (int t = 0; t < tiles_per_warp; ++t) {
