#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <mma.h>

using namespace cute;

__device__ __forceinline__ float h2f(__half h) { return __half2float(h); }
__device__ __forceinline__ __half f2h(float f) { return __float2half(f); }
__device__ __forceinline__ void my_cp_async_cg_16(void* smem_ptr, const void* gmem_ptr) {
    unsigned int smem_addr = static_cast<unsigned int>(__cvta_generic_to_shared(smem_ptr));
    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" :: "r"(smem_addr), "l"(gmem_ptr));
}
__device__ __forceinline__ void my_cp_async_commit() {
    asm volatile("cp.async.commit_group;\n");
}
template<int N>
__device__ __forceinline__ void my_cp_async_wait() {
    asm volatile("cp.async.wait_group %0;\n" :: "n"(N));
}

// Compile-time tile sizes.
constexpr int BLOCK_M = 32;   // rows of Q processed per CTA
constexpr int BLOCK_D = 32;   // chunk of head-dim processed at a time
constexpr int THREADS = 256;  // threads per block
constexpr int MAX_ACC = 64;   // upper bound of (BLOCK_M*N)/THREADS per thread

__global__ void attention_kernel(
    const __half* __restrict__ Q,
    const __half* __restrict__ K,
    const __half* __restrict__ V,
    __half* __restrict__ O,
    int B, int H, int N, int D,
    float scale)
{
    int b = blockIdx.z;
    int h = blockIdx.y;
    int m_tile = blockIdx.x;
    int m_base = m_tile * BLOCK_M;

    int64_t bh_stride = (int64_t)N * D;
    int64_t bh_idx = (int64_t)b * H + h;

    const __half* Qptr = Q + bh_idx * bh_stride;
    const __half* Kptr = K + bh_idx * bh_stride;
    const __half* Vptr = V + bh_idx * bh_stride;
    __half* Optr = O + bh_idx * bh_stride;

    auto mQ = make_tensor(make_gmem_ptr(Qptr), make_shape(N, D), make_stride(D, Int<1>{}));
    auto mK = make_tensor(make_gmem_ptr(Kptr), make_shape(N, D), make_stride(D, Int<1>{}));
    auto mV = make_tensor(make_gmem_ptr(Vptr), make_shape(N, D), make_stride(D, Int<1>{}));
    auto mO = make_tensor(make_gmem_ptr(Optr), make_shape(N, D), make_stride(D, Int<1>{}));

    extern __shared__ unsigned char smem_raw[];
    __half* Qs_buf0  = reinterpret_cast<__half*>(smem_raw);
    __half* Qs_buf1  = Qs_buf0 + BLOCK_M * BLOCK_D;
    __half* KVs_buf0 = Qs_buf1 + BLOCK_M * BLOCK_D;
    __half* KVs_buf1 = KVs_buf0 + (size_t)N * BLOCK_D;
    float*  S_ptr    = reinterpret_cast<float*>(KVs_buf1 + (size_t)N * BLOCK_D);
    auto sS  = make_tensor(make_smem_ptr(S_ptr),   make_shape(Int<BLOCK_M>{}, N), make_stride(N, Int<1>{}));
    __half* Ph_ptr   = reinterpret_cast<__half*>(S_ptr + (size_t)BLOCK_M * N);
    auto sP  = make_tensor(make_smem_ptr(Ph_ptr),  make_shape(Int<BLOCK_M>{}, N), make_stride(N, Int<1>{}));
    __half* Qbuf[2] = { Qs_buf0, Qs_buf1 };
    __half* Kbuf[2] = { KVs_buf0, KVs_buf1 };
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    int warp_id = tid / 32;
    int lane = tid % 32;
    int nwarps = nthreads / 32;
    int num_dchunks = D / BLOCK_D;
    int qelems8 = (BLOCK_M * BLOCK_D) / 8;
    int kelems8 = (N * BLOCK_D) / 8;
    auto load_qk_chunk = [&](int c, int buf) {
        int d0 = c * BLOCK_D;
        for (int idx = tid; idx < qelems8; idx += nthreads) {
            int m = idx / (BLOCK_D / 8);
            int d8 = idx % (BLOCK_D / 8);
            int gidx = (m_base + m) * D + d0 + d8 * 8;
            my_cp_async_cg_16(&Qbuf[buf][m * BLOCK_D + d8 * 8], &Qptr[gidx]);
        }
        for (int idx = tid; idx < kelems8; idx += nthreads) {
            int n = idx / (BLOCK_D / 8);
            int d8 = idx % (BLOCK_D / 8);
            int gidx = n * D + d0 + d8 * 8;
            my_cp_async_cg_16(&Kbuf[buf][n * BLOCK_D + d8 * 8], &Kptr[gidx]);
        }
        my_cp_async_commit();
    };
    // ---- Pass 1: S = Q @ K^T using Tensor Core WMMA (accumulated over head-dim chunks, double-buffered) ----
    constexpr int WMMA_M = 16, WMMA_N = 16, WMMA_K = 16;
    constexpr int MAX_TILES_PER_WARP = 8;
    const int num_m_tiles = BLOCK_M / WMMA_M;
    const int num_n_tiles = N / WMMA_N;
    const int num_wk_per_chunk = BLOCK_D / WMMA_K;
    const int total_tiles = num_m_tiles * num_n_tiles;
    const int tiles_per_warp = (total_tiles + nwarps - 1) / nwarps;
    nvcuda::wmma::fragment<nvcuda::wmma::accumulator, WMMA_M, WMMA_N, WMMA_K, float> acc_frag[MAX_TILES_PER_WARP];
    #pragma unroll
    for (int t = 0; t < MAX_TILES_PER_WARP; ++t) {
        nvcuda::wmma::fill_fragment(acc_frag[t], 0.0f);
    }
    int cur = 0;
    load_qk_chunk(0, cur);
    my_cp_async_wait<0>();
    __syncthreads();
    for (int c = 0; c < num_dchunks; ++c) {
        int nxt = 1 - cur;
        if (c + 1 < num_dchunks) {
            load_qk_chunk(c + 1, nxt);
        }
        __half* Qs_ptr = Qbuf[cur];
        __half* KVs_ptr = Kbuf[cur];
        for (int t = 0; t < tiles_per_warp; ++t) {
            int tile_idx = warp_id + t * nwarps;
            if (tile_idx >= total_tiles) continue;
            int mt = tile_idx / num_n_tiles;
            int nt = tile_idx % num_n_tiles;
            #pragma unroll
            for (int wk = 0; wk < num_wk_per_chunk; ++wk) {
                nvcuda::wmma::fragment<nvcuda::wmma::matrix_a, WMMA_M, WMMA_N, WMMA_K, __half, nvcuda::wmma::row_major> a_frag;
                nvcuda::wmma::fragment<nvcuda::wmma::matrix_b, WMMA_M, WMMA_N, WMMA_K, __half, nvcuda::wmma::col_major> b_frag;
                nvcuda::wmma::load_matrix_sync(a_frag, Qs_ptr + mt * WMMA_M * BLOCK_D + wk * WMMA_K, BLOCK_D);
                nvcuda::wmma::load_matrix_sync(b_frag, KVs_ptr + nt * WMMA_N * BLOCK_D + wk * WMMA_K, BLOCK_D);
                nvcuda::wmma::mma_sync(acc_frag[t], a_frag, b_frag, acc_frag[t]);
            }
        }
        if (c + 1 < num_dchunks) {
            my_cp_async_wait<0>();
        }
        __syncthreads();
        cur = nxt;
    }
    for (int t = 0; t < tiles_per_warp; ++t) {
        int tile_idx = warp_id + t * nwarps;
        if (tile_idx >= total_tiles) continue;
        int mt = tile_idx / num_n_tiles;
        int nt = tile_idx % num_n_tiles;
        #pragma unroll
        for (int e = 0; e < acc_frag[t].num_elements; ++e) {
            acc_frag[t].x[e] *= scale;
        }
        nvcuda::wmma::store_matrix_sync(S_ptr + mt * WMMA_M * N + nt * WMMA_N, acc_frag[t], N, nvcuda::wmma::mem_row_major);
    }
    __syncthreads();
    // ---- Softmax over each row of S (warp-parallel reduction) ----
    for (int m = warp_id; m < BLOCK_M; m += nwarps) {
        float maxv = -1e30f;
        for (int n = lane; n < N; n += 32) {
            float v = sS(m, n);
            maxv = fmaxf(maxv, v);
        }
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            maxv = fmaxf(maxv, __shfl_xor_sync(0xffffffff, maxv, offset));
        }
        float sumv = 0.0f;
        for (int n = lane; n < N; n += 32) {
            float e = expf(sS(m, n) - maxv);
            sS(m, n) = e;
            sumv += e;
        }
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            sumv += __shfl_xor_sync(0xffffffff, sumv, offset);
        }
        float inv = 1.0f / sumv;
        for (int n = lane; n < N; n += 32) {
            sS(m, n) = sS(m, n) * inv;
        }
    }
    __syncthreads();
    // Convert normalized probabilities to half precision for tensor-core P@V matmul
    for (int idx = tid; idx < BLOCK_M * N; idx += nthreads) {
        int m = idx / N;
        int n = idx % N;
        sP(m, n) = f2h(sS(m, n));
    }
    __syncthreads();
    // ---- Pass 2: O = P @ V using Tensor Core WMMA (accumulated over N via k-tiles, double-buffered over d chunks) ----
    const int num_om_tiles = BLOCK_M / WMMA_M;
    const int num_on_tiles = BLOCK_D / WMMA_N;
    const int total_o_tiles = num_om_tiles * num_on_tiles;
    const int o_tiles_per_warp = (total_o_tiles + nwarps - 1) / nwarps;
    const int num_k_tiles = N / WMMA_K;
    float* O_scratch = S_ptr; // reuse S_ptr smem (no longer needed after conversion to sP)
    int velems8 = (N * BLOCK_D) / 8;
    auto load_v_chunk = [&](int c, int buf) {
        int d0 = c * BLOCK_D;
        for (int idx = tid; idx < velems8; idx += nthreads) {
            int n = idx / (BLOCK_D / 8);
            int d8 = idx % (BLOCK_D / 8);
            int gidx = n * D + d0 + d8 * 8;
            my_cp_async_cg_16(&Kbuf[buf][n * BLOCK_D + d8 * 8], &Vptr[gidx]);
        }
        my_cp_async_commit();
    };
    cur = 0;
    load_v_chunk(0, cur);
    my_cp_async_wait<0>();
    __syncthreads();
    for (int c = 0; c < num_dchunks; ++c) {
        int nxt = 1 - cur;
        if (c + 1 < num_dchunks) {
            load_v_chunk(c + 1, nxt);
        }
        int d0 = c * BLOCK_D;
        __half* Vs_ptr = Kbuf[cur];
        nvcuda::wmma::fragment<nvcuda::wmma::accumulator, WMMA_M, WMMA_N, WMMA_K, float> o_acc[MAX_TILES_PER_WARP];
        #pragma unroll
        for (int t = 0; t < MAX_TILES_PER_WARP; ++t) {
            nvcuda::wmma::fill_fragment(o_acc[t], 0.0f);
        }
        for (int t = 0; t < o_tiles_per_warp; ++t) {
            int tile_idx = warp_id + t * nwarps;
            if (tile_idx >= total_o_tiles) continue;
            int mt = tile_idx / num_on_tiles;
            int nt = tile_idx % num_on_tiles;
            #pragma unroll 4
            for (int kt = 0; kt < num_k_tiles; ++kt) {
                nvcuda::wmma::fragment<nvcuda::wmma::matrix_a, WMMA_M, WMMA_N, WMMA_K, __half, nvcuda::wmma::row_major> p_frag;
                nvcuda::wmma::fragment<nvcuda::wmma::matrix_b, WMMA_M, WMMA_N, WMMA_K, __half, nvcuda::wmma::row_major> v_frag;
                nvcuda::wmma::load_matrix_sync(p_frag, Ph_ptr + mt * WMMA_M * N + kt * WMMA_K, N);
                nvcuda::wmma::load_matrix_sync(v_frag, Vs_ptr + kt * WMMA_K * BLOCK_D + nt * WMMA_N, BLOCK_D);
                nvcuda::wmma::mma_sync(o_acc[t], p_frag, v_frag, o_acc[t]);
            }
        }
        for (int t = 0; t < o_tiles_per_warp; ++t) {
            int tile_idx = warp_id + t * nwarps;
            if (tile_idx >= total_o_tiles) continue;
            int mt = tile_idx / num_on_tiles;
            int nt = tile_idx % num_on_tiles;
            nvcuda::wmma::store_matrix_sync(O_scratch + mt * WMMA_M * BLOCK_D + nt * WMMA_N, o_acc[t], BLOCK_D, nvcuda::wmma::mem_row_major);
        }
        __syncthreads();
        for (int idx = tid; idx < BLOCK_M * BLOCK_D; idx += nthreads) {
            int m = idx / BLOCK_D;
            int dl = idx % BLOCK_D;
            mO(m_base + m, d0 + dl) = f2h(O_scratch[idx]);
        }
        if (c + 1 < num_dchunks) {
            my_cp_async_wait<0>();
        }
        __syncthreads();
        cur = nxt;
    }
}
torch::Tensor cute_attention_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "Q,K,V must be CUDA tensors");
    TORCH_CHECK(Q.scalar_type() == at::kHalf, "expected fp16 tensors");
    TORCH_CHECK(K.scalar_type() == at::kHalf, "expected fp16 tensors");
    TORCH_CHECK(V.scalar_type() == at::kHalf, "expected fp16 tensors");
    TORCH_CHECK(Q.dim() == 4, "expected 4D tensor [B,H,N,D]");
    auto Qc = Q.contiguous();
    auto Kc = K.contiguous();
    auto Vc = V.contiguous();
    int B = (int)Qc.size(0);
    int H = (int)Qc.size(1);
    int N = (int)Qc.size(2);
    int D = (int)Qc.size(3);
    TORCH_CHECK(N % BLOCK_M == 0, "seq len must be divisible by BLOCK_M(=32)");
    TORCH_CHECK(D % BLOCK_D == 0, "head dim must be divisible by BLOCK_D(=64)");
    TORCH_CHECK((BLOCK_M * N) % THREADS == 0, "BLOCK_M*N must be divisible by THREADS");
    TORCH_CHECK((BLOCK_M * N) / THREADS <= MAX_ACC, "sequence length too large for this kernel configuration");
    auto O = torch::empty_like(Qc);
    float scale = 1.0f / sqrtf((float)D);
    dim3 grid(N / BLOCK_M, H, B);
    dim3 block(THREADS);
    size_t smem_bytes = 2 * ((size_t)BLOCK_M * BLOCK_D + (size_t)N * BLOCK_D) * sizeof(__half)
                       + (size_t)BLOCK_M * N * sizeof(float)
                       + (size_t)BLOCK_M * N * sizeof(__half);

    cudaError_t attrErr = cudaFuncSetAttribute(attention_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_bytes);
    TORCH_CHECK(attrErr == cudaSuccess, "cudaFuncSetAttribute failed (requested ", smem_bytes, " bytes dynamic shared mem): ", cudaGetErrorString(attrErr));

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    attention_kernel<<<grid, block, smem_bytes, stream>>>(
        reinterpret_cast<const __half*>(Qc.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(Kc.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(Vc.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(O.data_ptr<at::Half>()),
        B, H, N, D, scale
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "attention_kernel launch failed: ", cudaGetErrorString(err));

    return O;
}
